# Generated by test-lab — blind adversarial evaluation
"""The tone she picks must be the tone Chatterbox is asked for.

A reply gets two tones near it and they are not the same thing. The dream has a
dominant tension axis, which is what the journal was arguing about. The reply
has whatever she just said, which may be nothing like it -- she can answer a
question about a competence dream by admitting she does not know.

`map_mood(mood_label, contradictions)` takes the label as PROVENANCE only. It
returns it as persona_mood_label and never lets it pick a tone; the tone comes
from the axis. Passing her choice as that first argument therefore sent the axis
tone while recording hers, so the request and the record disagreed by
construction, every time, and the mismatch surfaced as a `tone_did_not_survive`
gate that read like a renderer fault. It was not: Chatterbox rendered exactly
what it was handed.

These tests pin the invariant that failure violated -- what we send equals what
we record -- rather than the specific pair that exposed it.
"""
from __future__ import annotations

import sys
from pathlib import Path

import pytest

SCRIPTS = Path(__file__).resolve().parents[1] / "scripts"
sys.path.insert(0, str(SCRIPTS))

import chatterbox_utterances  # noqa: E402
import speak_reply  # noqa: E402


@pytest.fixture()
def competence_dream(tmp_path: Path) -> Path:
    """A dream whose axis maps to memory_confident, so a mismatch is visible."""
    import json

    (tmp_path / "contradiction_report.json").write_text(
        json.dumps({"contradictions": [
            {"bridge_a": "Competence", "bridge_b": "Inadequacy"},
            {"bridge_a": "Competence", "bridge_b": "Inadequacy"},
        ]}),
        encoding="utf-8",
    )
    return tmp_path


def test_her_choice_is_what_gets_sent_not_just_what_gets_recorded(competence_dream):
    """The whole defect in one assertion."""
    tone, delivery = speak_reply.choose_tone(competence_dream, "curious_searching")
    assert tone == "curious_searching"
    assert delivery["tone"] == "curious_searching", (
        "the envelope carried the dream's axis tone while the record claimed hers"
    )


@pytest.mark.parametrize("chosen", sorted(speak_reply._load("map_delivery_tone").ALLOWED_TONES))
def test_every_tone_in_the_vocabulary_survives_the_round_trip(competence_dream, chosen):
    """One pair happened to expose this; the invariant is not about that pair."""
    tone, delivery = speak_reply.choose_tone(competence_dream, chosen)
    assert tone == chosen == delivery["tone"]


def test_pace_still_comes_from_the_dream(competence_dream):
    """Tone is about the reply; pace is not calibrated per-tone, so it stays."""
    _, delivery = speak_reply.choose_tone(competence_dream, "curious_searching")
    assert delivery["pace"] == "brisk", "Competence maps to brisk; that mapping is not hers to override"
    assert delivery["emotion_realization"] == "audible"


def test_a_tone_outside_the_vocabulary_falls_back_to_the_dream(competence_dream):
    """She may return junk. The dream's own axis is the honest default."""
    tone, delivery = speak_reply.choose_tone(competence_dream, "exposed, honest")
    assert tone == "memory_confident"
    assert delivery["tone"] == tone


def test_memory_uncertain_injects_multiple_native_chatterbox_event_tags():
    spoken, tags = speak_reply.inject_emotional_utterance(
        "I do not land cleanly. I am afraid the warmth will become proof.",
        "memory_uncertain",
    )
    assert spoken.startswith("[sniff] [sniff] ... I do not land cleanly.")
    assert len(tags) >= 2
    assert "[sigh]" in tags
    assert "[sniff]" in tags


def test_existing_native_event_tag_is_not_duplicated():
    spoken, tags = speak_reply.inject_emotional_utterance("[sniff] I am still here.", "memory_uncertain")
    assert spoken == "[sniff] ... I am still here."
    assert tags == ["[sniff]"]


def test_model_authored_tags_must_not_split_names_or_noun_phrases():
    assert speak_reply.has_bad_chatterbox_tag_boundary("I thought about [sniff] Kai.") is True
    assert speak_reply.has_bad_chatterbox_tag_boundary("I thought about Kai. [sniff]") is False
    assert speak_reply.has_bad_chatterbox_tag_boundary("[sniff] I thought about Kai.") is False


def test_reply_utterance_must_preserve_clean_reply_words():
    source = "Kai and the glowing box stayed with me because the room felt tender."
    assert chatterbox_utterances.preserves_source_words(source, "[sigh] Kai and the glowing box stayed with me ... because the room felt tender.") is True
    assert chatterbox_utterances.preserves_source_words(source, "[sigh] Marcus changed the meeting ... and I wanted breakfast.") is False


def test_shared_chatterbox_prompt_guidance_names_exact_pause_contract():
    guidance = chatterbox_utterances.prompt_guidance(include_clean_reply_rule=True)

    assert "Write the clean reply field with no Chatterbox bracket tags" in guidance
    assert "spaced ellipsis ( ... )" in guidance
    assert "crossfade_ms=0" in guidance
    assert "I thought about [sniff] Kai" in guidance


def test_reply_prompt_keeps_clean_text_separate_from_chatterbox_markup(tmp_path):
    (tmp_path / "journal.md").write_text("Kai and the glowing box stayed with me.\n", encoding="utf-8")
    prompt, asked = speak_reply.build_prompt(tmp_path, "What did the box change?")

    assert asked == "What did the box change?"
    assert "no Chatterbox\nbracket tags in the clean reply field" in prompt
    assert "The voice renderer reads this field, not the tone metadata" in prompt
    assert "Use spaces around ellipses" in prompt
    assert "Tags belong before a clause or\nafter a complete phrase" in prompt
    assert "clean transcript text with no Chatterbox tags" in prompt
    assert "pause_after_ms silence, stitched after each generated segment with crossfade_ms=0" in prompt


def test_speak_uses_zero_crossfade_for_exact_programmatic_pauses(tmp_path, monkeypatch):
    import json

    captured = {}
    source = tmp_path / "source.wav"
    source.write_bytes(b"RIFF....WAVE")

    class FakeResponse:
        def __enter__(self):
            return self

        def __exit__(self, *args):
            return False

        def read(self):
            return json.dumps({
                "ok": True,
                "engine": "chatterbox_turbo",
                "finished_response_audio": str(source),
                "render_plan": {"chunks": [{"pause_after_ms": 900}]},
                "crossfade_ms": 0,
            }).encode("utf-8")

    def fake_urlopen(req, timeout=300):
        captured["payload"] = json.loads(req.data.decode("utf-8"))
        return FakeResponse()

    monkeypatch.setattr(speak_reply.urllib.request, "urlopen", fake_urlopen)
    audio, response = speak_reply.speak(
        "[sigh] Kai stayed ... [sniff] and I noticed.",
        {"tone": "neutral_warm"},
        tmp_path,
        "reply-proof",
    )

    assert captured["payload"]["crossfade_ms"] == chatterbox_utterances.EXACT_PAUSE_CROSSFADE_MS
    assert captured["payload"]["render_chunks"]
    assert response["crossfade_ms"] == chatterbox_utterances.EXACT_PAUSE_CROSSFADE_MS
    assert audio == tmp_path / "reply-proof.wav"
    assert audio.is_file()


def test_collect_herself_cue_becomes_exact_programmatic_pause():
    text = chatterbox_utterances.normalize_collect_cues(
        "This is tender. [sniff] [sniff] give me a second. I can keep going."
    )
    chunks = chatterbox_utterances.compile_render_chunks(text, "memory_uncertain")
    assert "[sniff] [sniff] ... give me a second" in text
    assert len(chunks) >= 2
    assert any(int(chunk["pause_after_ms"]) >= 900 for chunk in chunks[:-1])
